var i=`1220-sancocho-panameno`;var a=`world-1220`;var t=`PA`;var s=`central-america-caribbean`;var o=4;var r=153;var g={en:`Sancocho Panameño`,ua:`Санкочо по-панамськи`};var l={en:`Sancocho Panameño is a dish from Panama featuring whole chicken, yellow onion, garlic, yam. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Санкочо по-панамськи, страва кухні країни Панама з такими основними складниками: ціла курка, жовта цибуля, часник, ямс. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var m=[{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 115 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 115 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:115,i:[[`whole-chicken`,1400,`g`],[`water`,2100,`ml`],[`yellow-onion`,160,`g`],[`garlic`,5,`clove`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 30 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 30 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:30,i:[[`yam`,370,`g`],[`cassava-root`,350,`g`],[`plantain`,320,`g`],[`dried-oregano`,5,`g`]]},{en:`Stir in these seasonings and additions. Taste, adjust the balance and let the dish stand briefly before serving.`,ua:`Додайте приправи та завершальні складники. Спробуйте, збалансуйте смак і дайте страві трохи настоятися перед подаванням.`,t:[`seasoning`,`finishing-with-herbs`],m:4,i:[[`table-salt`,null,`to_taste`],[`ground-black-pepper`,3,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`cilantro`,35,`g`],[`lime`,2,`pcs`]]}];var h={slug:i,id:a,country:`PA`,region:s,servings:4,minutes:153,title:g,text:l,steps:m};export{t as country,h as default,a as id,r as minutes,s as region,o as servings,i as slug,m as steps,l as text,g as title};